import numpy as np
import matplotlib.pyplot as plt

# Mostly generated by Microsoft Copilot

plt.rcParams.update({'font.size': 16})

# Symmetric quadratic function
def f(x):
    return x**2

# Plot range
x = np.linspace(-0.5, 0.5, 500)

# Symmetric tangent points
a = 0.2

# Function values and slopes
y_left = f(-a)
y_right = f(a)

m_left = 2 * (-a) # derivative of x^2 at x=-a
m_right = 2 * a # derivative of x^2 at x=a

# Tangent lines
tangent_left = m_left * (x + a) + y_left
tangent_right = m_right * (x - a) + y_right

# Tangent at the minimum (x = 0)
naive_tangent = np.zeros_like(x)

# Create figure
plt.figure(figsize=(7, 7))

# Symmetric function
plt.plot(
x, f(x),
linewidth=2,
label="Symmetric function"
)

# Symmetric linear approximations
plt.plot(
x, tangent_left,
"--",
linewidth=2,
color="tab:red",
label="Symmetric linear approximation"
)
plt.plot(
x, tangent_right,
"--",
linewidth=2,
color="tab:red"
)

# Naive linear approximation
plt.plot(
x, naive_tangent,
"-.",
linewidth=2,
color="tab:green",
label="Naive linear approximation"
)

# Mark tangent points
plt.scatter([-a, a, 0], [y_left, y_right, 0], color="black", zorder=5)

plt.title("Symmetry-aware Linearization Example")
plt.xlabel("x")
plt.ylabel("y")
plt.ylim((-0.3, 0.5))
plt.grid(True, alpha=0.3)
plt.legend()

plt.show()